    epsilonDecay: 0.99985,      // Per-step epsilon decay
    predatorExplorationRatio: 0.8, // Bias exploration towards safe lethal maneuvers

    // Dimensions (128-Feature Threat-Invariant Omni-Predator Tensor)
    stateDim: 128,
